import itertools
import json

YEARS = [1921, 1922, 1923, 1924]
STUDENTS = ["Louis", "Mollie", "Onyx", "Ryan", "Tiffany", "Yoshio"]


def valid(a):
    assigned = set(a.values())

    # Only Louis or Tiffany can be assigned to 1923.
    if a[1923] not in ("Louis", "Tiffany"):
        return False

    # If Mollie is assigned, she must be assigned to 1921 or 1922.
    mollie_years = [y for y in YEARS if a[y] == "Mollie"]
    if mollie_years and mollie_years[0] not in (1921, 1922):
        return False

    # If Tiffany is assigned, Ryan must be assigned.
    if "Tiffany" in assigned and "Ryan" not in assigned:
        return False

    # If Ryan is assigned, Onyx must be in the year immediately prior to Ryan's.
    if "Ryan" in assigned:
        ry = [y for y in YEARS if a[y] == "Ryan"][0]
        if (ry - 1) not in YEARS or a[ry - 1] != "Onyx":
            return False

    return True


# Exhaustive enumeration: each year gets exactly one distinct student.
all_assignments = []
for perm in itertools.permutations(STUDENTS, 4):
    all_assignments.append(dict(zip(YEARS, perm)))

# Condition: Yoshio is not assigned to the project.
scenarios = [a for a in all_assignments if "Yoshio" not in a.values()]
valid_scenarios = [a for a in scenarios if valid(a)]

options = {
    "A": lambda a: "Louis" not in a.values(),
    "B": lambda a: "Ryan" not in a.values(),
    "C": lambda a: "Tiffany" not in a.values(),
    "D": lambda a: a[1922] == "Onyx",
    "E": lambda a: a[1924] == "Louis",
}

could_be_true = {}
witness = {}
for key, pred in options.items():
    hits = [a for a in valid_scenarios if pred(a)]
    could_be_true[key] = len(hits) > 0
    if hits:
        witness[key] = {str(y): hits[0][y] for y in YEARS}

possible = [k for k in sorted(options) if could_be_true[k]]

if len(possible) == 1:
    final_answer = possible[0]
else:
    final_answer = "UNSUPPORTED"

result = {
    "final_answer": final_answer,
    "evidence": {
        "total_permutations": len(all_assignments),
        "scenarios_without_yoshio": len(scenarios),
        "valid_scenarios": len(valid_scenarios),
        "could_be_true": could_be_true,
        "witness_for_answer": witness.get(final_answer) if final_answer in witness else None,
    },
}

print(json.dumps(result, separators=(",", ":")))
